INSERT INTO directory_categories(slug,name,group_name,description,icon,verification_level,sort_order) VALUES
('csaladallitas','Családállítás','Alternatív és spirituális','Családállítással és rendszerállítással foglalkozó szolgáltatók. Nem egészségügyi vagy pszichoterápiás ellátás; nem helyettesíti az orvosi vagy pszichológiai kivizsgálást és kezelést.','◎','alternative',165),
('neurologia','Neurológia','Szakorvosi ellátás','Neurológiai szakrendelések és ideggyógyász szakorvosok. Az aktuális rendelésről, területi ellátásról és beutalási feltételekről a szolgáltatónál érdeklődj.','Ψ','healthcare',220),
('hipnoterapeutak','Hipnoterapeuták','Szakmai segítség','Hipnoterápiás képzettséget feltüntető szakemberek. Az egészségügyi alapvégzettség, a módszerspecifikus képesítés és az esetleges szupervízió az adatlapon és a forrásoldalon ellenőrizhető.','◉','healthcare',35),
('tesztek','Tesztek és szűrőkérdőívek','Vizsgálatok és diagnosztika','ADHD- és más pszichológiai szűrőkérdőívek, szakmai mérőeszközök és tesztforrások. Nem mind önkitöltős vagy magyar nyelvű. Egy szűrőeredmény önmagában nem diagnózis; az eszközök felhasználási feltételeit a forrásnál ellenőrizd.','▤','education',250),
('ful-orr-gegeszek','Fül-orr-gégészek','Szakorvosi ellátás','Fül-orr-gégész szakorvosok és szakrendelések. A megjelenés nem szakmai minősítés; az elérhetőséget és az ellátási feltételeket a szolgáltatónál ellenőrizd.','✚','healthcare',230),
('szemeszek','Szemészek','Szakorvosi ellátás','Szemész szakorvosok és szemészeti szakrendelések. A vizsgálatok és a gyermekellátás pontos köre szolgáltatónként eltérhet.','◉','healthcare',240),
('koponya-ct-mr','Koponya CT és MR','Vizsgálatok és diagnosztika','Koponya-CT- vagy MR-vizsgálatot nyújtó diagnosztikai helyek. Az adatlap nem orvosi vizsgálati javaslat. A megfelelő vizsgálatról, beutalóról és ellenjavallatokról orvossal és a vizsgálóhellyel egyeztess.','◎','healthcare',260),
('agykontroll','Agykontroll','Alternatív és spirituális','Agykontroll-oktatók és önfejlesztő tanfolyamok. Nem egészségügyi diagnosztikai vagy kezelési szolgáltatás, és nem helyettesíti az orvosi vagy pszichológiai ellátást.','◇','alternative',166),
('gyermekkori-diagnosztika','Gyermekkori diagnosztikák','Vizsgálatok és diagnosztika','Gyermekpszichiátriai, fejlődési, pszichológiai és gyógypedagógiai vizsgálatokat nyújtó intézmények. A vizsgálati kör, életkori határ, területi ellátás és a beutaló szükségessége a szolgáltatónál ellenőrizendő.','✚','healthcare',270),
('demencia','Demencia','Szakorvosi ellátás','Memóriazavarok és demencia kivizsgálásával, gondozásával, illetve hozzátartozói támogatással foglalkozó ellátóhelyek. A támogatói szolgáltatásokat megkülönböztetjük az orvosi diagnosztikától.','Ψ','healthcare',280)
